def get(i):return d['weisili_'+i]
def add(i,txt='',refs=()):
 c=get(i)
 if txt and txt not in c['biography']:c['biography']+=' '+txt
 c['evidence']+=list(refs)
 return c
def endpoint(i,s):
 c=get(i);c['version']['canonical_endpoint']=s;c['version']['deployment']=s+'；保留终局身体与本人技能，其他人的能力和未实际取得的设备不随卡自动调用。'
def trigger(i,s,c,a):get(i)['logic']['triggers'].append({'situation':s,'condition':c,'action':a})

